# Break My Fix finding 1, generated by Tracefix: _normalize_name_in_topic_msg raises AttributeError.
# Property (docstring): The payload dict maps the last item of the topic (the metric name) to the payload value.
# Quote: only support when the last item in the topic is the actual metric name
# Run it with pytest: it fails for as long as the code breaks this property.

from mqtt_exporter.main import _normalize_name_in_topic_msg


def test_break_my_fix_1() -> None:
    topic = 'shellies/power'
    payload = '1'
    # The property applies to this input: '/' in topic
    result = _normalize_name_in_topic_msg(topic=topic, payload=payload)
    assert (result[1] == {topic.split('/')[-1]: payload})
